/* [LUNI.13.6] the six canonical round modes. Wire-visible: the compiler
 * lowers the validated mode literal to one of these ints as a CALL argument,
 * so the values are append-only and permanent exactly like the op enum.
 * `half_*` differ ONLY at an exact tie; the other three never consult it. */
typedef enum {
    DS_ROUND_HALF_EVEN = 0,  /* ties to the even neighbour ("banker's") */
    DS_ROUND_HALF_UP   = 1,  /* ties away from zero                     */
    DS_ROUND_HALF_DOWN = 2,  /* ties toward zero                        */
    DS_ROUND_CEILING   = 3,  /* toward +inf                             */
    DS_ROUND_FLOOR     = 4,  /* toward -inf                             */
    DS_ROUND_TRUNCATE  = 5   /* toward zero                             */
} ds_currency_round_mode_t;

